-- Undo of 20261110000002: removes the terms this migration added (their aliases and work-term rows go with them: ON DELETE CASCADE) and empties the genres it filled.
delete from public.catalog_terms where name in ('Manga','Short stories','Children''s','Christian','Music','Paranormal','Religion','Spirituality','Sports','Cozy','Women''s fiction','Epic fantasy','Urban fantasy','Cozy mystery','Psychological thriller','Domestic thriller','Legal thriller','Historical romance','Contemporary romance','Space opera','Friendship','Family','Magic','Love','Murder','Social life and customs','New York Times bestseller','Prize winner','Reese''s Book Club','Oprah''s Book Club','Service95 Book Club','Reader favourite') and kind in ('genre','subgenre','subject','collection');
-- works.genres filled by this migration: single-term arrays that equal a removed genre term cannot be told apart from curated ones after the fact; re-run the E2 rule if needed.
update public.catalog_works set genres='{}' where cardinality(genres)=1 and genres[1] in ('Manga','Short stories','Children''s','Christian','Music','Paranormal','Religion','Spirituality','Sports','Cozy','Women''s fiction') and not exists (select 1 from public.catalog_terms t where t.kind='genre' and t.name=genres[1]);
